/**
 * Check the optional string argument.
 */
export function textIsShort(
  text: string | null
): boolean {
  return (
    (text === null)
    || OurCommon.lenStr(text) <= 10
  );
}

/**
 * Check the optional string argument compared for equality.
 */
export function textIsNotBanned(
  text: string | null
): boolean {
  return (
    (text === null)
    || text != "banned"
  );
}

/**
 * Check the optional argument passed on to another verification function.
 */
export function forwardsText(
  text: string | null
): boolean {
  return textIsNotBanned(text);
}

/**
 * Check the negated nullness check of the optional argument.
 */
export function textIsGiven(
  text: string | null
): boolean {
  return !(text === null);
}

/**
 * Check the optional integer argument.
 */
